/*
 * prog48_sorted_linked_list
 *
 * Re‑implementation of the original (obfuscated) binary.
 *
 * Behaviour:
 *   • If the program is started without any numeric arguments it prints
 *     the line "EMPTY\n".
 *   • Otherwise each command‑line argument is interpreted as a signed
 *     decimal integer (base 10).  Up to the first 64 numbers are kept;
 *     any additional arguments are ignored, exactly like the original.
 *   • The numbers are stored in a sorted linked‑list in *descending* order.
 *   • After all arguments have been processed the list is printed on a
 *     single line: each number is printed with "%ld", a single space
 *     separates consecutive numbers, and a final newline terminates the
 *     output.
 *
 * The original binary built the list manually; this version uses a simple
 * array and qsort for clarity while preserving the same observable output.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAX_VALUES 64          /* same limit as the original program */

static int cmp_desc(const void *a, const void *b)
{
    long av = *(const long *)a;
    long bv = *(const long *)b;
    if (av < bv) return 1;   /* larger values first */
    if (av > bv) return -1;
    return 0;
}

int main(int argc, char **argv)
{
    /* No numeric arguments → print EMPTY */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    /* Allocate space for at most MAX_VALUES numbers */
    long values[MAX_VALUES];
    int count = 0;

    /* Convert arguments to long integers, respecting the 64‑value limit */
    for (int i = 1; i < argc && count < MAX_VALUES; ++i) {
        char *endptr = NULL;
        long v = strtol(argv[i], &endptr, 10);
        /* The original program ignored conversion errors, so we do the same. */
        (void)endptr;               /* silence unused‑variable warning */
        values[count++] = v;
    }

    /* Sort in descending order (largest first) */
    qsort(values, (size_t)count, sizeof(long), cmp_desc);

    /* Print the sorted list */
    for (int i = 0; i < count; ++i) {
        if (i > 0) putchar(' ');
        printf("%ld", values[i]);
    }
    putchar('\n');

    return 0;
}
